/* Shared reference layer for the globe and every historical expedition. */
window.AtlasWater={add(map,prefix){map.addSource(prefix+'-lake-shapes',{type:'geojson',data:'water-lakes.geojson?v=20261031-water'});map.addLayer({id:prefix+'-lake-fill',type:'fill',source:prefix+'-lake-shapes',paint:{'fill-color':'#102630'}});map.addSource(prefix+'-water-labels',{type:'geojson',data:'water-labels.geojson?v=20261031-water',attribution:'Water names: Natural Earth · public domain'});for(const level of [0,2,3,4,5,6,7])map.addLayer({id:prefix+'-water-'+level,type:'symbol',source:prefix+'-water-labels',minzoom:level,filter:['==',['get','minzoom'],level],layout:{'text-field':['get','name'],'text-font':['Open Sans Italic','Arial Unicode MS Regular'],'text-size':['interpolate',['linear'],['zoom'],0,11,4,13,8,16],'text-max-width':10,'text-letter-spacing':.07,'text-padding':12,'symbol-sort-key':['get','rank'],'text-allow-overlap':false,'text-pitch-alignment':'viewport','text-rotation-alignment':'viewport'},paint:{'text-color':'#a4c3d2','text-halo-color':'#102630','text-halo-width':1.3,'text-opacity':.9}})},theme(map,prefix,light,ocean){if(map.getLayer(prefix+'-lake-fill'))map.setPaintProperty(prefix+'-lake-fill','fill-color',ocean);for(const level of [0,2,3,4,5,6,7]){const id=prefix+'-water-'+level;if(!map.getLayer(id))continue;map.setPaintProperty(id,'text-color',light?'#315565':'#accad8');map.setPaintProperty(id,'text-halo-color',ocean)}}};
